    pm.expect(body._links.self).to.eql(firstPage);
    pm.expect(body._links.first).to.eql(firstPage);
    pm.expect(body._links.previous).to.eql(null);

    if (body.pagination.totalPages > 1) {
        pm.expect(body._links.next).to.eql(
            "/pets?page=2&limit=1&species=Litoria+caerulea"
        );
    } else {
        pm.expect(body._links.next).to.eql(null);
    }
});

